import SiteInformationLinks from "../components/SiteInformationLinks.astro";
import AgentMetadata from '../components/AgentMetadata.astro';
import css from '../styles/global.css?raw';
interface Props { analytics?: boolean; title?: string; description?: string; socialImagePath?: string; socialImageWidth?: number; socialImageHeight?: number; socialImageAlt?: string; }
const {analytics = true, title = 'Kogen — Shape the feature. Leave the build to Kogen.', description = 'Make the product and UX decisions that define the feature. Kogen handles the implementation, checking, independent review, rework, and resulting commit.', socialImagePath = '/og.png', socialImageWidth = 1280, socialImageHeight = 640, socialImageAlt = 'Shape the feature. Leave the build to Kogen.'} = Astro.props;
const canonical = new URL(Astro.url.pathname, 'https://kogen.dev').href;
const socialImage = new URL(socialImagePath, 'https://kogen.dev').href;
---
<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width, initial-scale=1"/><title>{title}</title><meta name="description" content={description}/><link rel="canonical" href={canonical}/><meta property="og:type" content="website"/><meta property="og:title" content={title}/><meta property="og:description" content={description}/><meta property="og:url" content={canonical}/><meta property="og:image" content={socialImage}/><meta property="og:image:width" content={socialImageWidth}/><meta property="og:image:height" content={socialImageHeight}/><meta property="og:image:alt" content={socialImageAlt}/><meta name="twitter:card" content="summary_large_image"/><meta name="twitter:title" content={title}/><meta name="twitter:description" content={description}/><meta name="twitter:image" content={socialImage}/><meta name="twitter:image:alt" content={socialImageAlt}/><meta name="robots" content="index, follow"/><link rel="icon" href="/favicon.svg"/><style is:inline set:html={css}></style>{analytics && <script is:inline id="kogen-analytics">if (location.hostname === 'kogen.dev' || location.hostname === 'www.kogen.dev') {window.plausible=window.plausible||function(){(window.plausible.q=window.plausible.q||[]).push(arguments)};window.plausible.init=window.plausible.init||function(i){window.plausible.o=i||{}};window.plausible.init();var s=document.createElement('script');s.async=true;s.src='https://plausible.io/js/pa-YbJeNK89jzsIZPPvo5bQx.js';document.head.appendChild(s);}</script>}<AgentMetadata /></head><body><a class="skip" href="#main">Skip to content</a><header class="wrap"><a class="brand" href="/" aria-label="Kogen home"><img src="/brand/kogen-wordmark-black.svg" width="104" height="40" alt="Kogen" /></a><nav aria-label="Main navigation"><a href="/get-started/">Get started</a><a href="/learn/">Learn</a><a href="/#how-it-works">How it works</a><a href="/notes/">Notes</a><a href="/announcements/">Announcements</a><a href="/origins/">Origins</a></nav></header><slot/><footer class="wrap"><div><p>Made by <a href="https://almirsarajcic.com">Almir Sarajčić</a></p><a href="mailto:contact@kogen.dev">contact@kogen.dev</a></div><SiteInformationLinks /><div><a href="https://www.apache.org/licenses/LICENSE-2.0">Licensed under Apache 2.0</a><p>© 2026 Optimum Tech, LLC</p></div></footer><script is:inline id="copy-code">document.querySelectorAll('.prose pre, .start-prompt').forEach(function(pre){var code=pre.querySelector('code');if(!code)return;var box=document.createElement('div');box.className='code-block';pre.parentNode.insertBefore(box,pre);box.appendChild(pre);var button=document.createElement('button');button.className='copy-code';button.type='button';button.textContent='Copy';button.setAttribute('aria-label','Copy code to clipboard');button.addEventListener('click',async function(){try{await navigator.clipboard.writeText(code.textContent||'');button.textContent='Copied';setTimeout(function(){button.textContent='Copy'},1500)}catch(error){button.textContent='Could not copy';setTimeout(function(){button.textContent='Copy'},1500)}});box.appendChild(button)})</script></body></html>

